import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());String s = br.readLine();int antonWins = 0;int danikWins = 0;for (int i = 0; i < n; i++) {if (s.charAt(i) == 'A') {antonWins++;} else {danikWins++;}}if (antonWins > danikWins) {System.out.println("Anton");} else if (danikWins > antonWins) {System.out.println("Danik");} else {System.out.println("Friendship");}}}